// WideRow.java — one row of the un-normalized wide table
package com.nbi.db;

public class WideRow {
    // Composite key: (accountId, productCode)
    final String accountId;
    final String productCode;
    final String branchCode;   // depends on accountId only (partial)
    final String branchName;   // depends on accountId only (partial → 2NF breach)
    final String branchCity;   // depends on branchCode (transitive → 3NF breach)

    public WideRow(String accountId, String productCode, String branchCode,
                   String branchName, String branchCity) {
        this.accountId = accountId;
        this.productCode = productCode;
        this.branchCode = branchCode;
        this.branchName = branchName;
        this.branchCity = branchCity;
    }
}
