// NormalizationAnalyzer.java — detects breaches and reports normalized tables
package com.nbi.db;

import java.util.*;

public class NormalizationAnalyzer {

    // 2NF breach: a non-key column repeats identically for the same part-of-key.
    // If branchName is constant per accountId across differing productCode, it
    // depends only on part of the composite key -> partial dependency.
    public boolean hasPartialDependency(List<WideRow> rows) {
        Map<String, Set<String>> nameByAccount = new HashMap<>();
        Map<String, Set<String>> productsByAccount = new HashMap<>();
        for (WideRow r : rows) {
            nameByAccount.computeIfAbsent(r.accountId, k -> new HashSet<>()).add(r.branchName);
            productsByAccount.computeIfAbsent(r.accountId, k -> new HashSet<>()).add(r.productCode);
        }
        // partial dependency exists if some account has >1 product but 1 branchName
        for (String acc : productsByAccount.keySet()) {
            if (productsByAccount.get(acc).size() > 1
                    && nameByAccount.get(acc).size() == 1) {
                return true;
            }
        }
        return false;
    }

    // 3NF breach: branchCity is determined by branchCode (a non-key column).
    public boolean hasTransitiveDependency(List<WideRow> rows) {
        Map<String, String> cityByBranch = new HashMap<>();
        for (WideRow r : rows) {
            String prev = cityByBranch.putIfAbsent(r.branchCode, r.branchCity);
            // consistent branchCode -> branchCity mapping means a transitive dep
            if (prev != null && prev.equals(r.branchCity)) return true;
        }
        return false;
    }

    // Produce the normalized schema as a description.
    public List<String> normalize() {
        return List.of(
            "account(account_id PK, branch_code FK)            -- 2NF: branch facts off composite key",
            "account_product(account_id, product_code) PK      -- only key columns remain",
            "branch(branch_code PK, branch_name, branch_city)  -- 3NF: transitive city moved here"
        );
    }
}
