// Demo.java — shows both breaches then the normalized design
package com.nbi.db;

import java.util.List;

public class Demo {
    public static void main(String[] args) {
        List<WideRow> rows = List.of(
            new WideRow("A100", "SAV", "BR01", "Connaught Place", "New Delhi"),
            new WideRow("A100", "FD",  "BR01", "Connaught Place", "New Delhi"), // same acct, 2 products
            new WideRow("A200", "SAV", "BR02", "Bandra",          "Mumbai"),
            new WideRow("A300", "SAV", "BR01", "Connaught Place", "New Delhi")  // same branch repeats city
        );

        NormalizationAnalyzer an = new NormalizationAnalyzer();
        System.out.println("2NF breach (partial dependency, branchName on part-key)   = "
                + an.hasPartialDependency(rows));
        System.out.println("3NF breach (transitive dependency, city via branchCode)   = "
                + an.hasTransitiveDependency(rows));
        System.out.println("Normalized schema:");
        an.normalize().forEach(t -> System.out.println("  " + t));
    }
}
